mapper.select:
SELECT i.id, s.id AS settlement_id, s.settle_no, s.settle_date, s.partner_id, COALESCE(c.code, sp.code) AS partner_code, COALESCE(c.name, sp.name) AS partner_name, i.bill_id, b.bill_no, b.source_type, b.source_no, b.bill_date, b.amount AS bill_amount, s.currency, i.discount, i.discount_fc, s.remark, u.nickname AS create_by_name FROM fin_settlement_item i JOIN fin_settlement s ON s.id = i.settlement_id JOIN fin_bill b ON b.id = i.bill_id LEFT JOIN scm_customer c ON s.kind = 'RECEIPT' AND c.id = s.partner_id LEFT JOIN scm_supplier sp ON s.kind = 'PAYMENT' AND sp.id = s.partner_id LEFT JOIN sys_user u ON u.id = s.create_by WHERE s.kind = #{q.kind} AND s.status = 'APPROVED' AND i.discount <> 0 AND s.partner_id = #{q.partnerId} AND s.settle_date >= #{q.beginDate} AND s.settle_date <= #{q.endDate}
AND (s.settle_no LIKE CONCAT('%', #{q.keyword}, '%') OR b.bill_no LIKE CONCAT('%', #{q.keyword}, '%') OR b.source_no LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY s.settle_date DESC, s.id DESC, i.id
